code:
def solve(s):
    """Run-length encoding for any iterable.
    Returns a list of [element, count] pairs.
    If s is not iterable, treat it as a single element.
    """
    try:
        it = iter(s)
    except TypeError:
        # Not iterable, return single element encoding
        return [[s, 1]]
    # Get first element
    try:
        cur = next(it)
    except StopIteration:
        return []
    cnt = 1
    res = []
    for ch in it:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

