def solve(intervals):
    # Robust merge intervals handling possible malformed entries.
    # Filter out entries that are not length-2 sequences.
    clean = []
    for iv in intervals:
        try:
            if len(iv) >= 2:
                start, end = iv[0], iv[1]
                # Ensure comparable; if not numbers, skip.
                clean.append([start, end])
        except Exception:
            continue
    if not clean:
        return []
    # Sort by start (and end to stabilize)
    clean.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = clean[0]
    for s, e in clean[1:]:
        # Merge if overlapping or touching (s <= cur_end)
        if s <= cur_end:
            if e > cur_end:
                cur_end = e
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = s, e
    merged.append([cur_start, cur_end])
    return merged

