    """Count islands in a binary grid (4-directionally connected).
    grid: List of List of ints (0 or 1).
    Returns the number of distinct islands.
    """
    if not grid:
        return 0
    n, m = len(grid), len(grid[0])
    visited = [[False] * m for _ in range(n)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if i < 0 or i >= n or j < 0 or j >= m:
                continue
            if visited[i][j] or grid[i][j] == 0:
                continue
            visited[i][j] = True
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    islands = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

