def solve(grid):
    """Return number of islands (4-directionally connected 1s) in a possibly jagged grid.
    Handles grids where rows may have different lengths.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def bfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            # explore neighbors up, down, left, right
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < len(grid[nx]):
                    if (nx, ny) not in visited and grid[nx][ny] == 1:
                        stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                count += 1
                bfs(i, j)
    return count

